    enonce: "<span class=\"q\">1) </span>بيّن أنّ العدد <span dir=\"ltr\" class=\"expr\">2<sup>79</sup> - 2<sup>77</sup></span> يقبل القسمة على 12<br><span class=\"q\">2) </span>بيّن أنّ العدد <span dir=\"ltr\" class=\"expr\">2<sup>79</sup> - 2<sup>77</sup></span> <span dir=\"ltr\" class=\"expr\">3<sup>43</sup> + 3<sup>45</sup></span> يقبل القسمة على 18<br><span class=\"q\">3) </span>بيّن أنّ العدد <span dir=\"ltr\" class=\"expr\">2<sup>79</sup> - 2<sup>77</sup></span> <span dir=\"ltr\" class=\"expr\">3<sup>43</sup> + 3<sup>45</sup></span> <span dir=\"ltr\" class=\"expr\">2<sup>58</sup> + 16<sup>15</sup></span> يقبل القسمة على 20<br><span class=\"q\">4) </span>بيّن أنّ العدد <span dir=\"ltr\" class=\"expr\">2<sup>79</sup> - 2<sup>77</sup></span> <span dir=\"ltr\" class=\"expr\">3<sup>43</sup> + 3<sup>45</sup></span> <span dir=\"ltr\" class=\"expr\">2<sup>58</sup> + 16<sup>15</sup></span> <span dir=\"ltr\" class=\"expr\">5<sup>4</sup> + 5<sup>4</sup> + 5<sup>4</sup> + 5<sup>4</sup> + 5<sup>4</sup> + 5<sup>4</sup></span> يقبل القسمة على 75",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>79</sup> = 2<sup>77</sup> × 2<sup>2</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>79</sup> - 2<sup>77</sup> = 2<sup>77</sup>(2<sup>2</sup> - 1)</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">2<sup>2</sup> - 1 = 3</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">2<sup>79</sup> - 2<sup>77</sup> = 3 × 2<sup>77</sup></span>"},{"quoi":"نُظهر القاسم 12","math":"<span dir=\"ltr\" class=\"expr\">3 × 2<sup>77</sup> = 12 × 2<sup>75</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">12 × 2<sup>75</sup></span> و منه يقبل القسمة على 12"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>45</sup> = 3<sup>43</sup> × 3<sup>2</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>43</sup> + 3<sup>45</sup> = 3<sup>43</sup>(1 + 3<sup>2</sup></span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 + 3<sup>2</sup> = 10</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">3<sup>43</sup> + 3<sup>45</sup> = 10 × 3<sup>43</sup></span>"},{"quoi":"نُظهر القاسم 18","math":"<span dir=\"ltr\" class=\"expr\">10 × 3<sup>43</sup> = 18 × (5 × 3<sup>41</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">18 × 5 × 3<sup>41</sup></span> و منه يقبل القسمة على 18"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نوحّد الأساس","math":"<span dir=\"ltr\" class=\"expr\">16<sup>15</sup> = 2<sup>60</sup></span>"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>60</sup> = 2<sup>58</sup> × 2<sup>2</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>58</sup> + 2<sup>60</sup> = 2<sup>58</sup>(1 + 2<sup>2</sup></span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 + 2<sup>2</sup> = 5</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">2<sup>58</sup> + 16<sup>15</sup> = 5 × 2<sup>58</sup></span>"},{"quoi":"نُظهر القاسم 20","math":"<span dir=\"ltr\" class=\"expr\">5 × 2<sup>58</sup> = 20 × 2<sup>56</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">20 × 2<sup>56</sup></span> و منه يقبل القسمة على 20"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"الحدود متساوية","math":"الحدود 6 متساوية، و جمع 6 حدود متساوية هو ضربها في 6"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">5<sup>4</sup> + 5<sup>4</sup> + 5<sup>4</sup> + 5<sup>4</sup> + 5<sup>4</sup> + 5<sup>4</sup> = 6 × 5<sup>4</sup></span>"},{"quoi":"نُظهر القاسم 75","math":"<span dir=\"ltr\" class=\"expr\">6 × 5<sup>4</sup> = 75 × (2 × 5<sup>2</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">75 × 2 × 5<sup>2</sup></span> و منه يقبل القسمة على 75"}],
